@Test
public void testListTablesPagination() {
    AtomicInteger counter = new AtomicInteger(10);
    Mockito.doReturn(GetDatabaseResponse.builder().database(Database.builder().name("db1").build()).build()).when(glue).getDatabase(Mockito.any(GetDatabaseRequest.class));
    Mockito.doAnswer(new Answer() {

        @Override
        public Object answer(InvocationOnMock invocation) throws Throwable {
            if (counter.decrementAndGet() > 0) {
                return GetTablesResponse.builder().tableList(Table.builder().databaseName("db1").name(UUID.randomUUID().toString().replace("-", "")).parameters(ImmutableMap.of(BaseMetastoreTableOperations.TABLE_TYPE_PROP, BaseMetastoreTableOperations.ICEBERG_TABLE_TYPE_VALUE)).build()).nextToken("token").build();
            } else {
                return GetTablesResponse.builder().tableList(Table.builder().databaseName("db1").name("tb1").parameters(ImmutableMap.of(BaseMetastoreTableOperations.TABLE_TYPE_PROP, BaseMetastoreTableOperations.ICEBERG_TABLE_TYPE_VALUE)).build()).build();
            }
        }
    }).when(glue).getTables(Mockito.any(GetTablesRequest.class));
    Assert.assertEquals(10, glueCatalog.listTables(Namespace.of("db1")).size());
}

